    tree = original.copy(); tree.name = name; tree.nodes.clear(); g = _Nodes(tree)
    existing = {(s.in_out, s.name): s for s in tree.interface.items_tree if s.item_type == 'SOCKET'}
    for item in aggregate.interface.items_tree:
        if item.item_type != 'SOCKET' or item.in_out != 'INPUT': continue
