    kind = tree.interface.new_socket(name='Prepared Network Kind', in_out='INPUT', socket_type='NodeSocketInt')
    kind.default_value = ORIGINAL_SPANS; kind.min_value = 0; kind.max_value = 1
    kind.force_non_field = True
    kind.description = 'Prepared topology contract: 0 original spans, 1 explicit aggregate ports; set by the importer'
    evidence = tree.interface.new_socket(name='Aggregate Evidence', in_out='OUTPUT', socket_type='NodeSocketGeometry')
